// Proactive English B1 · Syria Edition · Book 2 · Unit 23 — Answer Key
const L = require('./lib');
const { p, h1, h2, pb, sp, box, table, C } = L;
const out = [];
const S = (t) => p(t, { bold: true, color: C.teal, before: 160, after: 60 });
const A = (t) => p(t, { indent: 200, after: 50 });
const SAMPLE = (paras) => box('Sample answer', paras, 'FFFFFF', C.navy);
const NOTE = (t) => box('Note', [t], C.lyellow, C.orange);

out.push(h1('Unit 23  The Wider News — Answer Key'));
out.push(p('_Proactive English · B1 · Book 2 · Syria Edition · Answer Key_', { color: '7F7F7F' }));
out.push(box('How to use this key', [
  'Every task has an answer or a **full sample**, including brainstorms, free speaking, reports, peer-review slips and homework.',
  '**One test runs through the unit and it is not _is it true_.** It is: **is there anybody in the sentence?** A report with a person in it can be checked by anybody with a telephone; a report with nobody in it can be neither relied on nor contradicted. Ask _who says so?_ of every sentence any student reads aloud, in every stage, and the unit teaches itself.',
  '**23.1 is built on two words and not on two stories.** The cycle needs each student\'s two items **and the one word that decided them**. A class that arrives with two stories and no words will spend the hour discussing the news, which is the one outcome to avoid: this unit is about reading, not about events.',
  '**23.2 is the cycle the rest of the unit rests on.** The reporting verb is where the writer\'s opinion lives, and the class will not have noticed it in a lifetime of reading. Teach the house rule hard: **write _said_ unless you can say out loud why you have chosen something else.**',
  '**23.5 needs the middle column defended.** Students have two columns — true and false — and everything in the middle gets sorted upwards within a fortnight. The middle column is the whole apparatus, and the thing that holds it in place is writing **who** said it beside the claim.',
  '**23.7 takes the prediction board down for the last time.** It must be in the room: if a class has lost it, reconstruct the sheet from the Unit 14 key and the four fallen dates from the Unit 18 key before the lesson, because the last fifteen minutes of the cycle are built on reading it. Two lines are dated 1 June — Jad\'s and Ms Huda\'s — and Jad\'s has already fallen, six months early, because of the forty-minute call in 22.5.',
  '**And the sentence the unit turns on**, which is Ms Huda\'s in 23.7: _a line with a date on it is the only kind of claim that can ever be settled._',
], C.lblue, C.navy));

// ===================== 23.1 =====================
out.push(pb());
out.push(h2('23.1  The one word that decided you'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open, and the instruction to enforce is **the word only, not the argument**. Students will want to retell the story; the whole value of the stage is in the two columns of single words on the board, and a class that has told eleven stories has no columns. Write them up and leave them up: 23.1\'s last stage reads them again.'));
out.push(A('**b** **2** and **4**. ✗ **1** has nobody in it at all. ✗ **3** _apparently_ is honest about being hearsay and still names nobody. ✗ **5** _it is understood_ sounds the most official of the five and has the least in it (23.3). Note what 4 has that 2 has not: **a day**. _The storeman told me on Tuesday_ can be checked against one man\'s memory of one day.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **A** – _seventeen_ made her believe the first; _many_ made her disbelieve the second (and _reportedly_ made it worse).'));
out.push(A('**b** **1** She could go to Aleppo and ask Nabil Zahra whether it is seventeen. She will not, but she could, and so could anybody — and with the second item there is nobody to ask at all.   **2** **Everything.** Three things can go wrong for a writer who names a source: the source can deny it, the figure can be counted again, and the name can be telephoned.'));
out.push(NOTE('The argument of this cycle is **cost**, and it is worth putting on the board in those words, because it is what makes the unit practical rather than cynical: _a sentence that puts nothing at risk is worth exactly what it cost._ Lubna\'s second finding is the one to press: she does not believe the presses, she believes **that somebody has accepted a cost**. That is the only kind of claim a reader at a distance is ever in a position to make, and it is a much more defensible position than believing or disbelieving the fact. The other thing to teach explicitly is the arithmetic of odd numbers: _seventeen of nineteen_ has been counted; _most_ has not; and _eighteen_ is what a person writes when repeating something they were told, because eighteen sounds like nineteen minus one.'));
out.push(S('Language box · Practise'));
out.push(SAMPLE([
  '**1** _According to the roads office notice of 11 December, the south side closes on the 19th._ / _The road is apparently closing on the 19th._',
  '**2** _The ward clerk told me on Monday that the notice and the specification are both on the board._ / _It seems the post has been advertised._',
  '**3** _According to the stores clerk, Abu Rashid, the December allocation is the same as November\'s._ / _I am told the allocation has doubled._',
  '**4** _The committee secretary\'s minute of 27 October says the meeting was adjourned._ / _Apparently the meeting was cancelled._',
  '**5** _According to the senior technician, who signed the sheet, lot 4471 was re-tested on 2 December._ / _The lot is reportedly re-tested._',
]));
out.push(A('Make the class say, for each pair, **what the second version costs the speaker** — and the answer is always nothing, which is the point. Then one further demand: in the attributed version, insist on a **date or a document**. _According to the stores clerk_ is better than _apparently_; _according to the stores clerk, Abu Rashid, on Monday_ is a different object again, because it can be checked in one conversation. ⚠ And collect _according to me_ as it happens; it is the commonest error of the cycle and it is a translation.'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**A:** Most of the staff are against it.',
  '**B:** Who says so, and how would they know?',
  '**B:** To check that I should have to ask about forty people, which nobody has done.',
  '**A:** According to the three night staff I spoke to on Tuesday, two of the three are against it and the third has not read it.',
  '**B:** Now I could telephone the three of them — and I notice that "most of the staff" has become three people, two of whom you have actually asked.',
]));
out.push(S('Stage 3R · Perform – listener task'));
out.push(A('Five or six of the eight bare versions contain a quantity word that costs nothing — _most_, _weeks_, _nobody_, _two of the machines_ — and the attributed versions almost always replace it with a figure. That is the finding and it is mechanical: **naming a source makes a writer count**, because the named person can be asked and the figure can be checked. Write the pairs in two columns so that the replacement is visible: _most_ → _two of three_; _weeks ago_ → _on 24 November_.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**a** _Believed: "According to the directorate\'s bulletin of 2 December, the maintenance contract for the eleven sites will go to tender in the spring." The word is "contract" — no: the word is "the eleven sites", because whoever wrote that had the list in front of them. To check it I should have to telephone the contracts office, which is four minutes. Not believed: "It is expected that staffing will be unaffected." The word is "expected". To check it I should have to find somebody who expects it, and there is nobody._',
  '**b** _My partner says the word to change in my second item is "expected" — one word, and the writer could have written "the contracts clerk says". Could the writer have written it? Yes: the clerk answered my own telephone call in two minutes. So the writer either did not ring or did ring and would not name her, and either way the sentence cost nothing._',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Lubna brought two items and did the hard part, which was one word each. The first she believed: a piece about a printing works in Aleppo, and the sentence was "according to the works foreman, Nabil Zahra, seventeen of the nineteen presses have been out of use since August". The word is seventeen. Omar asked why that word and not the name, and she said the name is what a careful writer puts in, but seventeen is what somebody counted — nobody invents seventeen. A writer who is inventing writes most, or nearly all; a writer repeating what he was told without checking writes eighteen, because eighteen sounds like nineteen minus one. The second item was a line in a trade bulletin: many depots are reportedly receiving double allocations this quarter. The word is many. Nour asked what is wrong with it, and Lubna said nothing is wrong with it — it is simply a word that costs the writer nothing, because two is many if you want it to be. And then the second word, which is worse: reportedly. Reported by whom? There is nobody in the sentence, and she cannot go and ask anybody anything. Omar asked what she can do with the first one, and she said she can go to Aleppo and ask Nabil Zahra whether it is seventeen — she will not, but she could, and so could anybody, and a man who has let his name and a figure be printed knows that. So what she believes is not the presses: she believes that somebody has put something at risk. Ms Huda said that is the sentence of the cycle and it is about cost — the foreman can deny it, the figure can be counted again, and the name can be telephoned, while "many depots are reportedly" puts nothing at risk, and a sentence that puts nothing at risk is worth exactly what it cost. And Lubna said she has always believed some things and not others, and had never once looked at the word.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ According to me, the figure is wrong. → ✓ _**In my view**_ _(according to is for other people)_.   ✗ According to that the foreman said… → ✓ _according to **the foreman**_ _(+ noun, never a clause)_.   ✗ It is reported from the roads office. → ✓ _reported **by**_.   ✗ Apparently that the road closed. → ✓ _**Apparently** the road closed_ _(no_ that_)_.   ✗ Many depots is receiving double allocations. → ✓ _many depots **are**_.   ✗ He told that the allocation had doubled. → ✓ _he told **me** that_, or _he **said** that_ _(18.5)_.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** Because the name is what a **careful writer** puts in, but _seventeen_ is a figure somebody has **counted**. A writer who is inventing writes _most_ or _nearly all_; a writer repeating what he was told writes _eighteen_, because eighteen sounds like nineteen minus one.'));
out.push(A('**2** Not the presses: **that a man has let his name and a figure be printed in the same sentence**, so three things can now go wrong for him and for whoever wrote it — a cost somebody has accepted. The second item would have been believable with either of two cheap things: a figure (_nine of the fourteen depots in this governorate_) or a source (_according to the bulletin\'s own correspondent, who has seen two of the allocation sheets_). The writer wrote neither.'));
out.push(A('**3** That she has read the bulletin for six years and never once looked at the words: she has believed and disbelieved **by feel**, and her feel has been doing this arithmetic without telling her.'));
out.push(A('The move to teach from the model is its **ending**. The page turns at the last paragraph from the writers to the reader, and that is what makes it a page worth keeping rather than a complaint about two journalists. Point out also that both items come from the **same bulletin and the same page** — which removes the lazy conclusion that some publications are reliable and others are not, and replaces it with the useful one: the sentence is the unit of trust, not the publication.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**TWO ITEMS AND THE WORD IN EACH** · R. Barakat · 20 December',
  '**The one I believed.** _"The three-night trial has been extended to all night staff with effect from 27 October."_ Committee minute, 27 October, which I have.',
  '**The word.** _Minute._ It is not a report of a decision; it is the decision. There is nothing between me and it.',
  '**And what I actually believe.** Not that the blocks are better. I believe that eleven people signed a page, and that whoever wrote it knew it would be read by the directorate.',
  '**The one I did not believe.** _"A second trolley is expected before the end of the year."_ Said to me by four people since August; nothing in writing anywhere.',
  '**The word.** _Expected._ Expected by whom? Four people said it and none of them is the person who orders trolleys.',
  '**What would have made me believe it.** An order number, or the name of the person who placed it. Both exist if the thing exists, and neither has ever been mentioned in five months.',
  '**And the uncomfortable part.** I repeated it to two patients\' relatives in September as though it were a date.',
]));
out.push(S('Stage 7 · Write freely (sample, 188 words)'));
out.push(SAMPLE([
  '**TWO ITEMS AND THE WORD IN EACH** · L. Sweidan · 19 December',
  '**The one I believed.** _"According to the works foreman, Nabil Zahra, seventeen of the nineteen presses have been out of use since August."_ Aleppo trade bulletin, 8 December.',
  '**The word.** Seventeen. Not the name, although the name is what a careful writer puts in. Seventeen is a figure somebody has counted. A writer who is inventing writes _most_ or _nearly all_; a writer repeating what he was told writes _eighteen_, because eighteen sounds like nineteen minus one.',
  '**And what I actually believe.** Not the presses. I believe that a man has let his name and a figure be printed in the same sentence, which means three things can now go wrong for him and for whoever wrote it. That is what I am believing: a cost that somebody has accepted.',
  '**The one I did not believe.** _"Many depots are reportedly receiving double allocations this quarter."_ Same bulletin, same page.',
  '**The two words.** _Many_ — two is many if the writer wants it to be, and the word costs nothing. And _reportedly_ — reported by whom? There is nobody in the sentence, so there is nobody to ask.',
  '**What would have made me believe it.** One of two things, and both are cheap. A figure: _nine of the fourteen depots in this governorate_. Or a source: _according to the bulletin\'s own correspondent, who has seen two of the allocation sheets_. The writer wrote neither, and had the whole page to do it on.',
  '**And the uncomfortable part.** I have read this bulletin for six years and have never once looked at the words. I have believed and disbelieved by feel, and my feel has been doing this arithmetic without telling me.',
]));
out.push(S('Stage 7P · Respond (sample slip — criterion named)'));
out.push(A('_Three sentences, each naming its criterion:_ **"On both sentences quoted exactly: they are, with the source and the date, and the fact that both come off the same page is the strongest thing on your sheet. On the one word named: _seventeen_ is right and the paragraph about _eighteen_ convinced me of it, which I did not expect. On the cheap improvement priced: _nine of the fourteen depots_ is exactly the right kind of example, and I would add how long it would have taken the writer to get it — a morning, at most."**'));
out.push(S('Stage 7R · Share'));
out.push(A('The two columns are the lesson and they should be read aloud, slowly. The believed column is almost all **figures and names**; the disbelieved column is almost all **quantity words** — _many, most, several, a number of_ — with two or three impersonal verbs. Say the conclusion in the form that carries into the rest of the unit: **nobody in this room was taught that, and everybody in this room has been using it.** The six cycles that follow are the same arithmetic done on purpose.'));
out.push(S('Homework (sample)'));
out.push(SAMPLE(['The claim I have repeated: that the directorate pays for the second trolley and not the ward. I asked the person who told me, and she had it from the stores clerk, and the stores clerk had it from a man who left in 2023. Three people, and the third one is not here to ask. So it has gone through at least three mouths and it ends at somebody nobody can question, which is where every one of these ends.']));

// ===================== 23.2 =====================
out.push(pb());
out.push(h2('23.2  Said, claimed, admitted, denied'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Seven verbs in one gap, and then the only question: **which makes the editors look worst, and why?** It is _admitted_, in almost every room, and the reason students give is the right one — _admitted_ says somebody had to get it out of them. _Claimed_ comes second and is the more interesting answer, because nothing has been asserted against the editors at all.'));
out.push(A('**b** **1** _refused to say_   **2** _announced_   **3** _claimed_   **4** _confirmed_   **5** _admitted_   **6** _denied_. ⚠ Note that **1** is the only one of the six that describes **an event**: the person was asked and did not answer, and that happened. The other five describe what somebody said.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **A** – _claim_, and it told him that the writer **would not vouch for it** — not that it was untrue.'));
out.push(A('**b** **1** Whether the fourth report was saying the change was untrue. It is not: it is saying _we are not vouching for this_, and then **the reader supplies the doubt**, so nobody has had to write a doubt down.   **2** **The reporting verb is where the writer\'s opinion lives.** Everything after the verb is the other person\'s sentence; the verb itself is the writer\'s.'));
out.push(NOTE('Two findings in this cycle are worth more than the table. The first is Jad\'s on **order of events**: _announced_ means they said it first, and _confirmed_ means somebody else said it first and they agreed afterwards — so a report that says _confirmed_ has told the reader that the thing leaked, without one word about leaking. One verb, and the reader knows the sequence. The second is Mazen\'s, and it is the one to press on a class that thinks this is subtle: a bulletin writing that the distributor _admitted_ replacing four units would have told its readers two things that are both false — that the replacement was against the distributor\'s interest and that somebody had to get it out of them. Neither was asserted; both were delivered. And the house rule that follows is the one to repeat for the rest of the course: **write _said_ unless you can say out loud exactly why you have chosen something else.**'));
out.push(S('Language box · Practise'));
out.push(SAMPLE([
  '**1** _The roads office **said** the road would reopen on the 22nd._ → _The roads office **has confirmed** that the road will reopen on the 22nd._ The second tells a reader that somebody had already reported the date — probably a driver.',
  '**2** _The clerk **said** the November figures were wrong._ → _The clerk **admitted** that the November figures were wrong._ The second makes the figures his fault, which nobody has asserted.',
  '**3** _The office **said** nobody was told._ → _The office **claimed** that nobody was told._ The second leaves the reader doubting it and nobody holding the doubt.',
  '**4** _The directorate **announced** that the post will be advertised._ → _The directorate **refused to say** when the post will be advertised._ The second is the only one of the pair that reports an event.',
  '**5** _The fitter **said** the second machine is out of use._ → _The second machine **is said to be** out of use._ The second has lost the fitter altogether (23.3).',
]));
out.push(A('In every pair make the class say **what the reader now concludes that nobody has written down**. That sentence is the whole cycle. ⚠ And drill the forms while the meaning is being discussed, because they are the examinable half: _admitted **taking** / admitted **that** he had taken_ · _denied **knowing** / denied **that** he knew_ · _refused **to say**_ · and _announce_ with no personal object — ~~he announced me~~ → _he **told me**_.'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**A:** The depot said that the notice went up three weeks late.',
  '**B:** The depot claimed that the notice went up three weeks late. — Now the reader thinks somebody disputes the three weeks.',
  '**B:** The depot admitted that the notice went up three weeks late. — Now the reader thinks somebody had to get it out of them, and that it matters more than it does.',
  '**A:** About myself I would write _said_, because the three weeks are on the notice itself and nobody had to ask me anything — and _admitted_ is the verb I would use about the depot if I were cross with it.',
]));
out.push(S('Stage 3R · Perform – listener task'));
out.push(A('The finding is in the last line of each turn, so make sure every speaker gives it: **which verb they chose about themselves.** It is _said_ or _announced_ almost every time, and almost nobody chooses _admitted_. Then the point that connects this cycle to 22.4: **the verb somebody else would use about you is the sentence you will have to answer** — and 22.4 was the practice for answering it. A student who can say _admitted is the verb they will use, and here is my two-sentence answer_ has both cycles.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**a** _Said: I said the bag was not checked against the receiving list. Claimed: I claimed the bag was not checked — which makes it sound as though somebody thinks it was. Admitted: I admitted the bag was not checked. A person who disliked me would write admitted, and they would not be wrong — it is against my interest and the senior technician did ask me. What I can say is that nobody had to ask twice._',
  '**b** _My partner\'s sentence with a refusal attached: "She refused to say how often bags had been left there." That is **not** true: I was not asked and I have written it into the bulletin item myself. The true version is: "No record exists, and the technician concerned says so in the item."_',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['The names change has been written about in four places, three of them saying the same thing and the fourth not, and it took Jad two days to see that the difference is one word. Two say the editors have announced that answers will carry names from January; one says they have confirmed it; and the fourth says the editors claim that answers will carry names. Nour asked whether the fourth is saying it is untrue, and Jad said that is what he could not work out: it is not saying it is untrue, it is saying "we are not vouching for this" — and then the reader does the rest, because a reader who meets "claim" assumes somebody doubts it, and nobody has had to write a doubt down. Omar asked about announced against confirmed, and Jad said announced means they said it first and officially, while confirmed means somebody else had already said it and the editors have now agreed — which tells you, without saying it, that the thing leaked before it was announced; one verb, and he knows the order of events. Then Mazen asked what a reader would think if a bulletin wrote that the distributor admitted replacing four units, and Jad said: that the replacement was against the distributor\'s interest and that somebody had to get it out of them. Mazen said neither is true — they offered, in writing, nine days after his letter. Ms Huda gave the rule, which is the shortest in the book: the reporting verb is where the writer\'s opinion lives. Everything after the verb is the other person\'s sentence and the verb itself is the writer\'s — said adds nothing, announced adds officialness, confirmed adds a previous report, claimed adds the writer\'s distance, admitted adds guilt, denied adds a charge, and refused to say is the only one of the seven that reports a fact rather than a claim. Jad said a reader notices none of it, and Ms Huda said almost no reader ever has — which is why the honest practice is to write said unless you can say out loud why you have chosen something else.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ He admitted to take the four units. → ✓ _admitted **taking**_ / _admitted **that** he had taken_.   ✗ He denied to know anything. → ✓ _denied **knowing**_ / _denied **that** he knew_.   ✗ He refused saying how many. → ✓ _refused **to say**_.   ✗ He announced me that the post would be advertised. → ✓ _he **told me** that_ / _he **announced** that_.   ✗ He said me that it was late. → ✓ _he **told** me_ / _he **said** that_.   ✗ The office claimed the figures to be wrong. → ✓ _claimed **that** the figures were wrong_.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** That **somebody else said it first and the editors agreed afterwards** — so a reader who knows the verbs now knows the change was reported before it was announced. Whoever wrote the word may not have meant it, and it is in print, and it is a fact about their office.'));
out.push(A('**2** Because **nothing has been asserted**: _claim_ says the writer will not vouch for it, the doubt is supplied by the reader, and nobody has had to write the doubt down — so there is nothing anybody can be held to and nothing to reply to.'));
out.push(A('**3** When the January change is announced on the page itself, put **the date it was decided and the name of the person who will answer questions about it**. It works because _claim_ is almost impossible to use about a sentence with a date and a name in it (23.1).'));
out.push(A('The paragraph to teach is **what I think happened, and I may be wrong**: _I think claim is that writer\'s ordinary verb for anything an organisation says about itself, and it goes in without being chosen._ The generous reading is also the likelier one, and it is the only one that leaves anybody anything to do — a note that accuses a writer of doubting you has to be answered, and a note that observes a habit can be acted on. Note too that the remedy is 19.4 again: one line of print, not a correction of somebody else.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**NOTE FOR THE DEPOT MANAGER · the weekly\'s four verbs** · T. Ayoub · 21 December',
  'This is not a complaint about anybody. It is four sentences about us with one word different.',
  '**What they say.** Two papers: _the directorate has confirmed that the first departure is 06.20_. One: _drivers claim that the timetable has been wrong since 2019_.',
  '**What _confirmed_ tells a reader.** That somebody said it before the directorate did. That somebody was us, and we said it for five years to anybody who would listen.',
  '**What _claim_ tells a reader.** Not that we are wrong. That the writer will not vouch for us — and two sentences later the same page has the directorate confirming the very thing we are said to claim.',
  '**What I think happened, and I may be wrong.** I do not think the writer doubts us. I think _claim_ is the ordinary verb for anything a group of employees says, and it goes in without being chosen.',
  '**What I am not asking for.** I am not asking anybody to write to the paper. The sentence has been read and the conclusion has been drawn.',
  '**The one thing worth doing, and it costs one line.** When the timetable is reprinted, print the date of the decision and the office that took it on the timetable itself.',
  '**And the thing about myself.** I have said "the office claims" about the roads office twice this year, both times without choosing it.',
]));
out.push(S('Stage 7 · Write freely (sample, 191 words)'));
out.push(SAMPLE([
  '**NOTE FOR THE EDITORS · the four reports of the January change** · J. Attar · 21 December',
  'This is not a complaint about anybody. It is four sentences with one word different, and I think the fourth one matters to you.',
  '**What the four say.** Two: _the editors have announced that answers will carry names from January._ One: _the editors have confirmed that answers will carry names._ One: _the editors claim that answers will carry names from January._',
  '**What _confirmed_ tells a reader.** That somebody else said it first and you agreed afterwards. Whoever wrote that word may not have meant it, but a reader who knows the verbs now knows that the change was reported before you announced it. That is one word, and it is a fact about your office, and it is in print.',
  '**What _claim_ tells a reader.** Not that it is untrue. That the writer will not vouch for it. The doubt is supplied by the reader and nobody has had to write it down, which is precisely why the word is used: it cannot be answered, because nothing has been asserted.',
  '**What I think happened, and I may be wrong.** I do not think the fourth writer doubts you. I think _claim_ is that writer\'s ordinary verb for anything an organisation says about itself, and it goes in without being chosen.',
  '**What I am not asking for.** I am not asking anybody to write to the fourth site. Three of us have already read it and drawn the conclusion, and a letter would not take the word out of the four hundred people who read it before us.',
  '**The one thing worth doing, and it costs one line.** When the January change is announced on the page itself, put the date you decided it on and the name of the person who will answer questions about it. _Claim_ is almost impossible to use about a sentence with a date and a name in it.',
  '**And the thing about myself.** I have used _claim_ twice in answers this year about equipment manufacturers, both times without choosing it, and I have gone back and changed both.',
]));
out.push(S('Stage 7P · Respond (sample slip — criterion named)'));
out.push(A('_Three sentences, each naming its criterion:_ **"On the versions quoted exactly: four sentences and the two identical ones both printed, which is the arithmetic and would have vanished in a paraphrase. On the verb explained and not denounced: _it goes in without being chosen_ is the sentence that makes the note answerable, and I would have written something much worse. On one use of your own: you found two and changed both, and the fact that you had to go and look is the part I shall copy."**'));
out.push(S('Stage 7R · Share'));
out.push(A('The count is predictable — _said_ or _announced_ about themselves, almost universally — and the conclusion is the bridge into 23.3 and back to 22.4: **the verb somebody else would use about you is the sentence you will have to answer.** End the stage by asking each student for the two-sentence answer (22.4) to the version of their own item that opens with _admitted_. A class that can do that has stopped being frightened of the word.'));
out.push(S('Homework (sample)'));
out.push(SAMPLE(['The report: "The ward has confirmed that the trial was extended in October." The verb is _confirmed_, and what it told me that the writer never wrote down is that somebody outside the ward knew about the extension before the ward said anything — which is true: the night staff were telling each other on the 28th and the minute was not circulated until the 6th of November. One word, and it has dated a leak nobody has ever mentioned.']));

// ===================== 23.3 =====================
out.push(pb());
out.push(h2('23.3  It is understood that'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** One sentence each, and then the teacher\'s single question: **who?** Nobody will be able to answer, and the silence is the stage. Do not rescue it by supplying a plausible source; the whole point is that the student has carried the sentence about for a fortnight without the question having occurred to them.'));
out.push(A('**b** **1** _The auditor reported that the figures were wrong._   **2** _The ward clerk says that nobody was told._   **3** _The fitter says the machine is out of use._   **4** _His clerk says he sent the letter in October._   **5** ⚠ **usually nobody will go in.** A future with no author is the commonest kind of impersonal report, and 5 is there to be the one that defeats the exercise — the class should be allowed to fail it, because that is the finding.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **A** – five of the nine; the other four have **nobody to put in**, and he sat with them for an hour.'));
out.push(A('**b** **1** It makes eleven men ask him about it, and he can tell each of them nothing, which costs about two minutes each — whereas a signed notice could have been checked in four minutes and the eleven told by half past six.   **2** _X **is said to be**_ is **now**; _X **is said to have been**_ is **earlier**. One word, _have_, and the sentence has moved into the past.'));
out.push(NOTE('This is 19.1 arriving in print, five units later, and the test is the same: **put a person in front of it.** What is new is the pair of facts about a sentence with nobody in it, and students should be made to say them in this order, because the second is the one that explains the first: **it cannot be contradicted, and it cannot be relied on** — and ⚠ the first of those two is the reason it was written. Tareq\'s pattern is worth the board: the impersonal reports that **defeat** the rewrite are the ones about **the future** (_will be withdrawn_, _will continue_, _will be reprinted_), because a future has no witness. And the sentence to leave the class with is the practical one, for those of them who write notices: _a signed notice is a thing you can act on; an unsigned one is a thing you can only worry about._'));
out.push(S('Language box · Practise'));
